const roadCurve=(z,progress=0)=>4.4*(Math.sin((z+progress)*.017)-Math.sin(progress*.017))+.65*(Math.sin((z+progress)*.036)-Math.sin(progress*.036));
function makeRoadRibbon(width,material,segments=240){const positions=new Float32Array((segments+1)*2*3),indices=[];for(let i=0;i<segments;i++){const a=i*2,b=a+1,c=a+2,d=a+3;indices.push(a,b,c,b,d,c)}const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.BufferAttribute(positions,3));geometry.setIndex(indices);const mesh=new THREE.Mesh(geometry,material);mesh.frustumCulled=false;mesh.receiveShadow=true;scene.add(mesh);mesh.userData.update=(progress)=>{const attr=geometry.attributes.position;for(let i=0;i<=segments;i++){const z=-80+i*1.5,cx=roadCurve(z,progress),j=i*6;attr.array[j]=cx-width/2;attr.array[j+1]=-.045;attr.array[j+2]=z;attr.array[j+3]=cx+width/2;attr.array[j+4]=-.045;attr.array[j+5]=z}attr.needsUpdate=true;geometry.computeVertexNormals()};mesh.userData.update(0);return mesh}
