Index: index.html
===================================================================
--- index.html
+++ index.html
@@ -12,9 +12,9 @@
 #game{position:fixed;inset:0;pointer-events:none;padding:env(safe-area-inset-top) 0 env(safe-area-inset-bottom)}
 .topbar{position:absolute;top:max(14px,env(safe-area-inset-top));left:16px;right:16px;display:flex;align-items:flex-start;justify-content:space-between;gap:12px}
 .brand{display:flex;align-items:center;gap:10px;padding:9px 14px 9px 9px;border-radius:18px;background:#fff9e8e8;box-shadow:var(--shadow);backdrop-filter:blur(8px)}.brand-icon{width:38px;height:38px;border-radius:13px;background:#0d8585;display:grid;place-items:center;color:#fff;font-size:22px}.brand b{display:block;font-size:14px;letter-spacing:.08em}.brand small{display:block;color:#64716a;font-size:10px;font-weight:800;letter-spacing:.14em;margin-top:2px}
 .hud{display:flex;gap:8px}.pill{min-width:88px;padding:9px 13px;border-radius:15px;background:#fff9e8e8;box-shadow:var(--shadow);backdrop-filter:blur(8px)}.pill span{font-size:9px;letter-spacing:.12em;font-weight:900;color:#738079;display:block}.pill strong{font-size:17px;line-height:1.35}.pill .unit{font-size:10px;color:#75817a}
-.top-actions{display:flex;gap:7px}.icon-btn{pointer-events:auto;border:0;width:41px;height:41px;border-radius:14px;background:#fff9e8e8;color:var(--ink);box-shadow:var(--shadow);font-size:18px;cursor:pointer}
+.top-actions{display:flex;gap:7px}.icon-btn{pointer-events:auto;border:0;width:41px;height:41px;border-radius:14px;background:#fff9e8e8;color:var(--ink);box-shadow:var(--shadow);font-size:18px;cursor:pointer;touch-action:manipulation}.icon-btn:active,.icon-btn.pressed{background:#ffcf74;transform:scale(.94)}
