input.command:
node --input-type=module -e '
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const runtime=process.env.HOME+"/.local/share/omgithub-playwright";
const require=createRequire(runtime+"/package.json");
const {chromium}=require("playwright");
const cfg=JSON.parse(readFileSync(runtime+"/linux.json","utf8"));
process.env.DISPLAY ||= ":"+readFileSync(runtime+"/display","utf8").trim();
const browser=await chromium.launch({...cfg.browser.launchOptions});
const errors=[];
const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
page.on("pageerror",e=>errors.push(e.message));
page.on("console",m=>{if(m.type()==="error") errors.push("console: "+m.text())});
const res=await page.goto("http://localhost:3000",{waitUntil:"load",timeout:45000});
await page.locator("#playBtn").click();
await page.waitForTimeout(1400);
const desktop=await page.evaluate(()=>({title:document.title,canvas:!!document.querySelector("canvas"),canvasSize:[document.querySelector("canvas")?.width,document.querySelector("canvas")?.height],overlayHidden:document.querySelector("#overlay").classList.contains("hidden"),brand:document.querySelector(".brand")?.innerText,overflow:document.documentElement.scrollWidth>innerWidth}));
await page.locator("#hornBtn").click();
const hornPressed=await page.locator("#hornBtn").evaluate(e=>e.classList.contains("pressed"));
await page.screenshot({path:"screenshots/latest.jpg",type:"jpeg",quality:82});
await page.setViewportSize({width:390,height:844});
await page.waitForTimeout(500);
const mobile=await page.evaluate(()=>({viewport:[innerWidth,innerHeight],overflow:document.documentElement.scrollWidth>innerWidth,controlsVisible:["#leftBtn","#rightBtn","#gasBtn","#brakeBtn"].every(s=>{const r=document.querySelector(s).getBoundingClientRect();return r.width>0&&r.left>=0&&r.right<=innerWidth&&r.top>=0&&r.bottom<=innerHeight}),brand:document.querySelector(".brand")?.innerText}));
console.log(JSON.stringify({httpStatus:res.status(),desktop,mobile,hornPressed,errors},null,2));
await browser.close();
if(res.status()!==200||!desktop.canvas||!desktop.overlayHidden||desktop.overflow||mobile.overflow||!mobile.controlsVisible||errors.length)process.exitCode=1;
'

