 const traffic=[];for(let i=0;i<8;i++){const bike=i%3===0,vehicle=bike?makeBike(['#e4a52d','#c84e3e','#187f82'][i%3]):makeCar(['#d75b42','#e6bd52','#387d86','#e8e1c8'][i%4]);const direction=i%2?1:-1;vehicle.userData.lane=direction>0?-1:1;vehicle.userData.direction=direction;vehicle.userData.speed=bike?3.2:1.6;vehicle.position.set(0,0,28+i*27);vehicle.rotation.y=direction<0?Math.PI:0;scene.add(vehicle);traffic.push(vehicle)}
